An $m$th-order $n$-dimensional symmetric tensor $\mathcal{T}= (t_{i_1 i_2 ...i_m})$ is called
\begin{itemize}
	\item[(i)] \textbf{copositive}  \cite{qi2013symmetric} if
	$\mathcal{T} x^m = \sum\limits_{i_1,i_2,\dots ,i_m=1}^{n} t_{i_1 i_2...i_m} x_{i_1}x_{i_2}...x_{i_m} \geq 0$ for all nonegative vector $x=(x_1,x_2,...,x_n)^T$;
	\item[(ii)]   \textbf{strictly  copositive} \cite{qi2013symmetric} if $\mathcal{T} x^m >0$ for all nonegative and nonzero vector $x=(x_1,x_2,...,x_n)^T$;
	\item[(iii)]  \textbf{positive   (semi)-definite} \cite{qi2005eigenvalues} if $\mathcal{T} x^m \geq(>) 0$ for all nonzero vector $x \in \mathbb{R}^n$ and an even positive integer $m$.
\end{itemize}

\label{lem:26}
	Let $\mathcal{T}$ be a 4th order 2-dimensional symmetric tensor with its entries $|t_{ijkl}|=1$. Then $\mathcal{T}$ is strictly copositive if and only if
	$$t_{1111}=t_{2222}=1, \begin{cases}
				t_{1112}=t_{1222}=1;\\
		t_{1112}t_{1222}=-1\mbox{ and }  t_{1122}=1.
	\end{cases}$$

\label{thm:31}
	 Let $\mathcal{T}=(t_{ijkl})$ be a $4$th-order $n$-dimensional symmetric tensor. Then
 $\mathcal{T}$ is strictly copositive  if and only if $$\begin{cases}
		x\in\mathbb{R}_+^n\mbox{ and  }	\mathcal{T}x^4=0\ \Longrightarrow\ x=0,\\
		\mbox{there is a }y\in\mathbb{R}^n_+\setminus\{0\}\mbox{ such that }\mathcal{T}y^4>0;
	\end{cases}$$
